      "path": "package.json",
      "content": "{\n  \"name\": \"@weibaohui/skills-management\",\n  \"version\": \"0.9.3\",\n  \"description\": \"dsh 插件 · 技能市场：一个页面管理本机所有 coding agent 的技能（Claude、ZCode、Codex 等十余个执行器），一键收编进 DSH 用户库供 skill 工具调用；内置 6600+ ntd 技能市场可浏览搜索安装，支持注入开销（≈token/字符）统计与排序、模型可见性治理与市场每日自动同步。\",\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"cordis\",\n    \"plugin\",\n    \"skills\",\n    \"marketplace\",\n    \"ntd\",\n    \"dsh-plugin\"\n  ],\n  \"main\": \"src/index.js\",\n  \"exports\": {\n    \".\": \"./src/index.js\",\n    \"./client\": \"./client/bundle.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"engines\": {\n    \"node\": \">=22.5\",\n    \"dsh\": \">=0.1.7-rc.2\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"src\",\n    \"client\",\n    \"cordis.patch.yml\"\n  ],\n  \"scripts\": {\n    \"check\": \"node --check src/index.js && node --check client/index.js\",\n    \"test\": \"node --test test/*.test.mjs\",\n    \"build:client\": \"node scripts/build-client.mjs\",\n    \"prepublishOnly\": \"npm run build:client && npm run check && npm test\"\n  },\n  \"dependencies\": {\n    \"@weibaohui/dsh-plugin-kit\": \"^0.2.0\",\n    \"js-tiktoken\": \"^1.0.21\",\n    \"yaml\": \"^2.9.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.4\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/weibaohui/skills-management.git\"\n  },\n  \"homepage\": \"https://github.com/weibaohui/skills-management#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/weibaohui/skills-management/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  }\n}\n"
